// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Could you add a tab completion into P set inside the definicion tab, it should take items from T and N and make the available to complete. Make sure to distinguis if it is from T or N with border and background of different color"
// Changes: Rules (P) editor with symbol completion from N and T – popup at the caret, Tab/Enter accepts,
//          arrows move, Esc closes, Ctrl+Space lists everything; N items are sky, T items amber.

import { useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent } from 'react'
import { cx, fieldClass } from './ui'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: No keyboard trap – Tab only accepts a suggestion or opens the list after ->/| (decided in rulesKeys), it no
//          longer inserts spaces, Shift+Tab is never taken, Esc closes and lets the next Tab leave; IME-safe Enter.
//          Completion is exposed to assistive tech: aria-controls/aria-activedescendant on the textbox, listbox/option
//          with useId ids and aria-selected, and a debounced polite count announcement. Label/description by id.
import { rulesEditorKey, suggestionAnnouncement } from './rulesKeys'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Can you add support for inline comments to P definition"
// Changes: Shared comment detection.
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Comments and quoting come from the symbol syntax module, the same rules the parser of P reads with.
import { quote, stripComment } from '#/lib/symbols'

export interface CompletionSymbol {
  symbol: string
  kind: 'N' | 'T' | 'ε'
  note?: string
}

interface Popup {
  start: number
  end: number
  prefix: string
  top: number
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "in the definition tab when the completion menu is opened near the bottom of the screen it clip, make it open up from the cursor"
  // Changes: Top edge of the caret line – the anchor when the popup opens upwards.
  caretTop: number
  left: number
  forced: boolean
  lhs: boolean
}

const MAX_ITEMS = 8
const KIND_STYLE = {
  N: 'border-sky-400/50 bg-sky-500/15 text-sky-100',
  T: 'border-amber-400/50 bg-amber-500/15 text-amber-100',
  ε: 'border-violet-400/50 bg-violet-500/15 text-violet-100',
} as const
const KIND_NAME = { N: 'neterminál', T: 'terminál', ε: 'epsilon' } as const
// The active option is also outlined (rings are box-shadows, which forced-colours mode removes).
const KIND_ACTIVE = {
  N: 'ring-2 ring-sky-300/80 bg-sky-500/30 forced-colors:outline-2 forced-colors:outline-[Highlight]',
  T: 'ring-2 ring-amber-300/80 bg-amber-500/30 forced-colors:outline-2 forced-colors:outline-[Highlight]',
  ε: 'ring-2 ring-violet-300/80 bg-violet-500/30 forced-colors:outline-2 forced-colors:outline-[Highlight]',
} as const

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Could you also include eps as default when nothing is typed"
// Changes: ε-rule entry: first item when nothing is typed, also found by typing `eps`/`ε`.
const EPS: CompletionSymbol = { symbol: 'ε', kind: 'ε', note: 'prázdna pravá strana' }
const epsScore = (query: string) => {
  const scores = [matchScore('ε', query), matchScore('eps', query), matchScore('epsilon', query)].filter((x): x is number => x !== null)
  // Only prefix-like matches – a stray `e` inside a word should not keep offering ε.
  const best = Math.min(...scores)
  return best <= 2 ? best : null
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Could you make it so when i type functy it will show FUNC_TYPE for completion"
// Changes: Match quality of a symbol for the typed word (lower = better, null = no match). Case and '_'
//          are ignored, so `functy` finds FUNC_TYPE; as a last resort the letters only need to appear in order.
const loose = (s: string) => s.toLowerCase().replace(/_/g, '')
function matchScore(symbol: string, query: string): number | null {
  if (!query || symbol.startsWith(query)) return 0
  if (symbol.toLowerCase().startsWith(query.toLowerCase())) return 1
  const sym = loose(symbol)
  const q = loose(query)
  if (!q) return 2
  if (sym.startsWith(q)) return 2
  const at = sym.indexOf(q)
  if (at >= 0) return 3 + at / 100
  let gaps = 0
  let i = 0
  for (const ch of q) {
    const next = sym.indexOf(ch, i)
    if (next < 0) return null
    gaps += next - i
    i = next + 1
  }
  return 4 + gaps / 100
}

// Caret position inside the textarea via an off-screen mirror element with the same text metrics.
function caretOffset(ta: HTMLTextAreaElement, index: number) {
  const style = getComputedStyle(ta)
  const mirror = document.createElement('div')
  for (const prop of ['fontFamily', 'fontSize', 'fontWeight', 'lineHeight', 'letterSpacing', 'tabSize', 'paddingTop', 'paddingLeft', 'borderTopWidth', 'borderLeftWidth', 'boxSizing'] as const) {
    mirror.style[prop] = style[prop]
  }
  Object.assign(mirror.style, { position: 'absolute', visibility: 'hidden', whiteSpace: 'pre', top: '0', left: '-9999px' })
  mirror.textContent = ta.value.slice(0, index)
  const marker = document.createElement('span')
  marker.textContent = '​'
  mirror.appendChild(marker)
  document.body.appendChild(mirror)
  const pos = { top: marker.offsetTop - ta.scrollTop, left: marker.offsetLeft - ta.scrollLeft, line: parseFloat(style.lineHeight) || 20 }
  mirror.remove()
  return pos
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "in the definition tab when the completion menu is opened near the bottom of the screen it clip, make it open up from the cursor"
// Changes: Visible vertical range for an element – the viewport narrowed by every ancestor that clips its overflow.
function visibleRange(el: HTMLElement) {
  let top = 0
  let bottom = window.innerHeight
  for (let node = el.parentElement; node; node = node.parentElement) {
    const { overflowY } = getComputedStyle(node)
    if (overflowY === 'visible') continue
    const rect = node.getBoundingClientRect()
    top = Math.max(top, rect.top)
    bottom = Math.min(bottom, rect.bottom)
  }
  return { top, bottom }
}

export function RulesEditor({
  value,
  onChange,
  symbols,
  placeholder,
  rows = 18,
  derived = false,
  fill = false,
  labelledBy,
  describedBy,
}: {
  value: string
  onChange: (value: string) => void
  symbols: CompletionSymbol[]
  placeholder?: string
  rows?: number
  /** Symbols come from P itself, so the word being typed is among them and must not be offered. */
  derived?: boolean
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "could you also tweak the vertical spacing so that the 2 panes will fit onto the screen"
  // Changes: On wide screens stretch to the parent's height instead of a fixed number of rows.
  fill?: boolean
  /** Id of the visible label (falls back to aria-label "Pravidlá P"). */
  labelledBy?: string
  /** Id of the visible help text describing the editor and its keys. */
  describedBy?: string
}) {
  const ref = useRef<HTMLTextAreaElement>(null)
  const [popup, setPopup] = useState<Popup | null>(null)
  const [active, setActive] = useState(0)
  const pendingCaret = useRef<number | null>(null)
  const pointer = useRef<{ x: number; y: number } | null>(null)
  const frame = useRef<number | null>(null)
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "in the definition tab when the completion menu is opened near the bottom of the screen it clip, make it open up from the cursor"
  // Changes: The popup opens above the caret when it would not fit below it.
  const wrapper = useRef<HTMLDivElement>(null)
  const list = useRef<HTMLUListElement>(null)
  const [up, setUp] = useState(false)
  const listId = useId()
  const optionId = (i: number) => `${listId}-o${i}`
  // Caret position where Esc closed the list – the next Tab there moves focus instead of reopening it.
  const dismissedAt = useRef<number | null>(null)

  const items = useMemo(() => {
    if (!popup) return []
    const p = popup.prefix
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Could you make it so when i type functy it will show FUNC_TYPE for completion"
    // Changes: Fuzzy matching (case- and underscore-insensitive, letters in order) instead of prefix/substring only.
    const scored = symbols
      .filter((s) => !derived || s.symbol !== p)
      .map((s) => ({ s, score: matchScore(s.symbol, p) }))
      .filter((x): x is { s: CompletionSymbol; score: number } => x.score !== null)
    // The first word of a rule is its left side, so offer nonterminals first there.
    const rank = (s: CompletionSymbol) => (popup.lhs && s.kind === 'T' ? 1 : 0)
    const list = scored.sort((a, b) => rank(a.s) - rank(b.s) || a.score - b.score).map((x) => x.s)
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Could you also include eps as default when nothing is typed"
    // Changes: ε is the default (first) item for an empty word on a right-hand side, and matches `eps`.
    if (!popup.lhs) {
      const eps = p ? epsScore(p) : -1
      if (eps !== null) {
        const at = eps < 0 ? 0 : scored.findIndex((x) => x.score > eps)
        list.splice(at < 0 ? list.length : at, 0, EPS)
      }
    }
    // Nothing to offer when the word is already complete and unambiguous.
    if (!popup.forced && list.length === 1 && list[0].symbol === p) return []
    return list.slice(0, MAX_ITEMS)
  }, [popup, symbols, derived])

  // Debounced polite announcement of the suggestion count (typing changes the list on every key).
  const shownCount = popup ? items.length : 0
  const [announcement, setAnnouncement] = useState('')
  useEffect(() => {
    const t = setTimeout(() => setAnnouncement(suggestionAnnouncement(shownCount)), shownCount ? 500 : 0)
    return () => clearTimeout(t)
  }, [shownCount, popup?.start, popup?.forced])

  useLayoutEffect(() => {
    if (pendingCaret.current === null || !ref.current) return
    ref.current.setSelectionRange(pendingCaret.current, pendingCaret.current)
    pendingCaret.current = null
  })

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "in the definition tab when the completion menu is opened near the bottom of the screen it clip, make it open up from the cursor"
  // Changes: Before paint, flip the popup above the caret when there is not enough visible room below it.
  useLayoutEffect(() => {
    if (!popup || !list.current || !wrapper.current) return
    const height = list.current.offsetHeight
    const origin = wrapper.current.getBoundingClientRect().top
    const range = visibleRange(wrapper.current)
    const below = range.bottom - (origin + popup.top)
    const above = origin + popup.caretTop - range.top
    setUp(height > below && above > below)
  }, [popup, items])

  const refresh = (forced = false) => {
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Could you also include eps as default when nothing is typed"
    // Changes: An explicit request wins over a still-pending refresh from typing (it would close the list again).
    if (forced && frame.current !== null) {
      cancelAnimationFrame(frame.current)
      frame.current = null
    }
    const ta = ref.current
    if (!ta || ta.selectionStart !== ta.selectionEnd) return setPopup(null)
    const caret = ta.selectionStart
    const text = ta.value
    let start = caret
    while (start > 0 && !/\s/.test(text[start - 1])) start--
    let end = caret
    while (end < text.length && !/\s/.test(text[end])) end++
    const prefix = text.slice(start, caret)
    const lineStart = text.lastIndexOf('\n', caret - 1) + 1
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Can you add support for inline comments to P definition"
    // Changes: No completion anywhere inside a comment, including an inline one after the rule.
    const beforeWord = text.slice(lineStart, start)
    if ((!prefix && !forced) || prefix.startsWith('#') || stripComment(beforeWord) !== beforeWord) return setPopup(null)
    const pos = caretOffset(ta, start)
    const lhs = !text.slice(lineStart, start).trim()
    setPopup({ start, end, prefix, top: ta.offsetTop + pos.top + pos.line + 4, caretTop: ta.offsetTop + pos.top - 4, left: ta.offsetLeft + Math.max(0, pos.left), forced, lhs })
    setActive(0)
  }

  const accept = (item: CompletionSymbol) => {
    if (!popup) return
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
    // Changes: Shared quoting – E' is inserted as E' (it used to become "E'", a different nonterminal on the left side).
    const insert = item === EPS ? item.symbol : quote(item.symbol)
    const after = value.slice(popup.end)
    // Leave the caret after one space: reuse an existing one, otherwise add it.
    pendingCaret.current = popup.start + insert.length + 1
    onChange(value.slice(0, popup.start) + insert + (after.startsWith(' ') ? '' : ' ') + after)
    setPopup(null)
  }

  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    const ta = e.currentTarget
    const action = rulesEditorKey(
      { key: e.key, shiftKey: e.shiftKey, ctrlKey: e.ctrlKey, altKey: e.altKey, metaKey: e.metaKey, isComposing: e.nativeEvent.isComposing, keyCode: e.keyCode },
      {
        popupOpen: !!popup && items.length > 0,
        beforeCaret: ta.value.slice(ta.value.lastIndexOf('\n', ta.selectionStart - 1) + 1, ta.selectionStart),
        hasSelection: ta.selectionStart !== ta.selectionEnd,
        dismissed: dismissedAt.current === ta.selectionStart,
      },
    )
    if (!action) return
    e.preventDefault()
    switch (action) {
      case 'showAll':
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "Could you also include eps as default when nothing is typed"
      // Changes: Tab on an empty right-hand side (after `->` or `|`) opens the completion with ε preselected.
      case 'open':
        dismissedAt.current = null
        return refresh(true)
      case 'next':
      case 'prev': {
        const dir = action === 'next' ? 1 : -1
        return setActive((i) => (i + dir + items.length) % items.length)
      }
      case 'accept':
        return accept(items[Math.min(active, items.length - 1)])
      case 'close':
        dismissedAt.current = ta.selectionStart
        return setPopup(null)
    }
  }

  const open = !!popup && items.length > 0
  const activeIndex = Math.min(active, items.length - 1)

  return (
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "could you also tweak the vertical spacing so that the 2 panes will fit onto the screen"
    // Changes: fill – wrapper and textarea grow with the parent flex column.
    <div ref={wrapper} className={cx('relative', fill && 'lg:flex lg:min-h-0 lg:flex-1 lg:flex-col')}>
      <textarea
        ref={ref}
        rows={rows}
        wrap="off"
        spellCheck={false}
        value={value}
        placeholder={placeholder}
        {...(labelledBy ? { 'aria-labelledby': labelledBy } : { 'aria-label': 'Pravidlá P' })}
        aria-describedby={describedBy}
        aria-autocomplete="list"
        aria-controls={open ? listId : undefined}
        aria-activedescendant={open ? optionId(activeIndex) : undefined}
        className={cx(fieldClass, 'resize-y', fill && 'lg:min-h-24 lg:flex-1 lg:resize-none')}
        onChange={(e) => {
          dismissedAt.current = null
          onChange(e.target.value)
          // AI generated by: Claude Code / claude-opus-5-5
          // Prompt: "Could you also include eps as default when nothing is typed"
          // Changes: Keep the frame id so an explicit Tab/Ctrl+Space can cancel this deferred refresh.
          if (frame.current !== null) cancelAnimationFrame(frame.current)
          frame.current = requestAnimationFrame(() => {
            frame.current = null
            refresh()
          })
        }}
        onKeyDown={onKeyDown}
        onClick={() => setPopup(null)}
        onBlur={() => setPopup(null)}
        onScroll={() => setPopup(null)}
      />
      <div role="status" className="sr-only">
        {announcement}
      </div>
      {open && (
        <ul
          ref={list}
          id={listId}
          role="listbox"
          aria-label="Návrhy symbolov"
          className="absolute z-30 grid max-w-[min(22rem,calc(100%-1rem))] min-w-44 gap-1 rounded-xl border border-white/10 bg-zinc-950/95 p-1.5 shadow-2xl shadow-black/60 backdrop-blur"
          // AI generated by: Claude Code / claude-opus-5-5
          // Prompt: "in the definition tab when the completion menu is opened near the bottom of the screen it clip, make it open up from the cursor"
          // Changes: Anchor the bottom edge just above the caret line when opening upwards.
          style={{ ...(up ? { bottom: (wrapper.current?.offsetHeight ?? 0) - popup.caretTop } : { top: popup.top }), left: Math.max(0, Math.min(popup.left, (ref.current?.clientWidth ?? 400) - 180)) }}
        >
          {items.map((item, i) => (
            <li
              key={item.kind + item.symbol}
              id={optionId(i)}
              role="option"
              aria-selected={i === activeIndex}
              onMouseDown={(e) => {
                e.preventDefault()
                accept(item)
              }}
              onMouseMove={(e) => {
                // Only real pointer movement selects – a popup opening under a resting cursor must not steal the selection.
                const last = pointer.current
                pointer.current = { x: e.clientX, y: e.clientY }
                if (last && (last.x !== e.clientX || last.y !== e.clientY)) setActive(i)
              }}
              className={cx(
                'flex cursor-pointer items-center gap-2 rounded-lg border px-2 py-1 font-mono text-[13px]',
                KIND_STYLE[item.kind],
                i === activeIndex && KIND_ACTIVE[item.kind],
              )}
            >
              <span aria-hidden="true" className="rounded bg-black/30 px-1 text-[10px] font-semibold">
                {item.kind}
              </span>
              <span className="truncate">{item.symbol}</span>
              <span className="sr-only">, {KIND_NAME[item.kind]}</span>
              {item.note && <span className="ml-auto truncate pl-2 font-sans text-[11px] opacity-70">{item.note}</span>}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
